  padding: 0;
}

/* ── Tokens ─────────────────────────────────────────────────── */
:root {
  --bg:           #0d0f14;
  --surface:      #161a23;
  --surface-alt:  #1e2330;
  --border:       #2e3347;
  --border-focus: #7b8cde;
  --text:         #e4e7f0;
  --text-muted:   #8890a8;
  --accent:       #7b8cde;
  --accent-hover: #9aa8e8;
  --error:        #f87171;
  --error-bg:     #2a1212;
  --success:      #4ade80;
  --success-bg:   #0d2318;
  --check-bg:     #7b8cde;
  --radius:       10px;
  --radius-sm:    6px;
}

/* ── Body / layout ──────────────────────────────────────────── */
body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
  background-color: var(--bg);
  background-image:
    radial-gradient(ellipse 60% 40% at 50% 0%, #1c2240 0%, transparent 70%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

main {
  width: 100%;
  max-width: 480px;
}

/* ── Card ───────────────────────────────────────────────────── */
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2.25rem 2rem;
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.04) inset,
    0 8px 32px rgba(0, 0, 0, 0.5);
}

/* ── Heading ────────────────────────────────────────────────── */
h1 {
  font-size: 1.375rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--text);
  margin-bottom: 0.375rem;
}

.intro {
  color: var(--text-muted);
  font-size: 0.9375rem;
  margin-bottom: 1.75rem;
}

/* ── Form ───────────────────────────────────────────────────── */
form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

/* ── Form field wrapper ─────────────────────────────────────── */
.form-field {
  background: var(--surface-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 1rem 1.125rem;
  transition: border-color 0.15s ease;
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* ── Checkbox row ───────────────────────────────────────────── */
.checkbox-row {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
}

/* ── Custom checkbox ────────────────────────────────────────── */
input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  margin-top: 0.2em; /* optical alignment with label text */
  border: 2px solid var(--border);
  border-radius: 4px;
  background: var(--surface);
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;
  position: relative;
}

input[type="checkbox"]:hover {
  border-color: var(--accent);
}

input[type="checkbox"]:checked {
  background: var(--check-bg);
  border-color: var(--check-bg);
}

/* Checkmark via clip-path */
input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  inset: 0;
  background: white;
  clip-path: polygon(14% 50%, 8% 64%, 38% 90%, 92% 22%, 79% 12%, 38% 65%);
}

/* Focus ring — clearly visible, 3:1+ contrast */
input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(123, 140, 222, 0.25);
}

/* ── Label ──────────────────────────────────────────────────── */
label[for="agree-terms"] {
  font-size: 0.9375rem;
  cursor: pointer;
  line-height: 1.5;
}

label[for="agree-terms"] a {
  color: var(--accent);
  text-decoration: underline;
  text-underline-offset: 2px;
  transition: color 0.15s ease;
}

label[for="agree-terms"] a:hover,
label[for="agree-terms"] a:focus-visible {
  color: var(--accent-hover);
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  border-radius: 2px;
}

.required-mark {
  color: var(--error);
  margin-left: 0.125rem;
}

/* ── Helper text ────────────────────────────────────────────── */
.helper-text {
  margin-top: 0.5rem;
  font-size: 0.8125rem;
  color: var(--text-muted);
  padding-left: calc(1.125rem + 0.625rem); /* align under label */
}

/* ── Error state ────────────────────────────────────────────── */
.error-text {
  margin-top: 0.5rem;
  font-size: 0.8125rem;
  color: var(--error);
  padding-left: calc(1.125rem + 0.625rem);
  font-weight: 500;
}

.form-field.is-invalid {
  border-color: var(--error);
  background: var(--error-bg);
}

/* ── Required legend ────────────────────────────────────────── */
.required-legend {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: -0.25rem;
}

.required-legend span {
  color: var(--error);
  margin-right: 0.125rem;
}

/* ── Submit button ──────────────────────────────────────────── */
button[type="submit"] {
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--accent);
  color: #0d0f14;
  font-size: 0.9375rem;
  font-weight: 700;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  letter-spacing: 0.01em;
  transition: background 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:active {
  transform: translateY(1px);
}

button[type="submit"]:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(123, 140, 222, 0.25);
}

/* ── Success banner ─────────────────────────────────────────── */
.success-banner {
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  background: var(--success-bg);
  border: 1px solid var(--success);
  border-radius: var(--radius-sm);
  color: var(--success);
  font-size: 0.9375rem;
  font-weight: 600;
}

/* ── Reduced motion ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ── Forced colors (high-contrast mode) ────────────────────── */
@media (forced-colors: active) {
  input[type="checkbox"]:checked {
    forced-color-adjust: none;
    background: Highlight;
    border-color: Highlight;
  }
  input[type="checkbox"]:checked::after {
    background: HighlightText;
  }
  button[type="submit"] {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }
}

/* ── Reflow at 320px ────────────────────────────────────────── */
@media (max-width: 360px) {
  .card {
    padding: 1.5rem 1.125rem;
  }
}
